pub unsafe fn is_dtbclk_required(dc:*const dc, c:*mut dc_state)->bool { for i in 0..(*(*dc).res_pool).pipe_count as usize { let p=&(*c).res_ctx.pipe_ctx[i]; if p.stream.is_null(){continue;} if dc_is_hdmi_frl_signal((*p.stream).signal)||is_dp2p0_output_encoder(p){return true;} } false }

