unsafe fn populate_pipe_ctx_dlg_params_from_dml(p:*mut pipe_ctx,m:*mut display_mode_lib_st,idx:dml_uint_t){ let t=&(*(*p).stream).timing; let ha=t.h_addressable+t.h_border_left+t.h_border_right; let va=t.v_addressable+t.v_border_bottom+t.v_border_top; let hs=t.h_total-t.h_front_porch; let vs=t.v_total-t.v_front_porch; let he=hs-t.h_addressable-t.h_border_left-t.h_border_right; let ve=vs-t.v_addressable-t.v_border_top-t.v_border_bottom; (*p).pipe_dlg_param.vstartup_start=dml_get_vstartup_calculated(m,idx); (*p).pipe_dlg_param.vupdate_offset=dml_get_vupdate_offset(m,idx); (*p).pipe_dlg_param.vupdate_width=dml_get_vupdate_width(m,idx); (*p).pipe_dlg_param.vready_offset=dml_get_vready_offset(m,idx); ASSERT!((*p).stream_res.tg.inst<=0xff); (*p).pipe_dlg_param.otg_inst=(*p).stream_res.tg.inst as u8; (*p).pipe_dlg_param.hactive=ha; (*p).pipe_dlg_param.vactive=va; (*p).pipe_dlg_param.htotal=t.h_total; (*p).pipe_dlg_param.vtotal=t.v_total; (*p).pipe_dlg_param.hblank_end=he; (*p).pipe_dlg_param.vblank_end=ve; (*p).pipe_dlg_param.hblank_start=hs; (*p).pipe_dlg_param.vblank_start=vs; (*p).pipe_dlg_param.vfront_porch=t.v_front_porch; (*p).pipe_dlg_param.pixel_rate_mhz=t.pix_clk_100hz as f64/10000.0; (*p).pipe_dlg_param.refresh_rate=((t.pix_clk_100hz*100)/t.h_total)/t.v_total; (*p).pipe_dlg_param.vtotal_max=(*p).stream.adjust.v_total_max; (*p).pipe_dlg_param.vtotal_min=(*p).stream.adjust.v_total_min; (*p).pipe_dlg_param.recout_height=(*p).plane_res.scl_data.recout.height; (*p).pipe_dlg_param.recout_width=(*p).plane_res.scl_data.recout.width; (*p).pipe_dlg_param.full_recout_height=(*p).plane_res.scl_data.recout.height; (*p).pipe_dlg_param.full_recout_width=(*p).plane_res.scl_data.recout.width; }

