pub unsafe fn dml2_calc_max_scaled_time(t:u32,mode:mmhubbub_wbif_mode,u:u32)->u32 { let mut b=if mode==PACKED_444{t/4}else if mode==PACKED_444_FP16{t/8}else{0}; if b==0{b=1;} ((0xb40*b*32)>>6)-u }

