pub unsafe fn dml2_calculate_rq_and_dlg_params(dc:*const dc,ctx:*mut dc_state,out:*mut resource_context,in_ctx:*mut dml2_context,pipe_cnt:u32){
    (*ctx).bw_ctx.bw.dcn.clk.dcfclk_deep_sleep_khz=((*in_ctx).v20.dml_core_ctx.mp.DCFCLKDeepSleep*1000.0) as u32; (*ctx).bw_ctx.bw.dcn.clk.dppclk_khz=0;
    (*ctx).bw_ctx.bw.dcn.clk.fclk_p_state_change_support=(*in_ctx).v20.dml_core_ctx.ms.support.FCLKChangeSupport[0]!=dml_fclock_change_unsupported;
    if (*ctx).bw_ctx.bw.dcn.clk.dispclk_khz<(*dc).debug.min_disp_clk_khz{(*ctx).bw_ctx.bw.dcn.clk.dispclk_khz=(*dc).debug.min_disp_clk_khz;}
    (*ctx).bw_ctx.bw.dcn.compbuf_size_kb=(*in_ctx).v20.dml_core_ctx.ip.config_return_buffer_size_in_kbytes;
    for ci in 0..pipe_cnt as usize { let p=&mut (*ctx).res_ctx.pipe_ctx[ci]; if p.stream.is_null(){continue;} let mut id=0; let di=if get_plane_id(in_ctx,ctx,p.plane_state,(*p.stream).stream_id,(*in_ctx).v20.scratch.dml_to_dc_pipe_mapping.dml_pipe_idx_to_plane_index[p.pipe_idx as usize],&mut id){find_dml_pipe_idx_by_plane_id(in_ctx,id)}else{dml2_helper_find_dml_pipe_idx_by_stream_id(in_ctx,(*p.stream).stream_id)}; if di<0||di==0x7fffffff{continue;} let di=di as usize; ASSERT!((*in_ctx).v20.scratch.dml_to_dc_pipe_mapping.dml_pipe_idx_to_stream_id_valid[di]); populate_pipe_ctx_dlg_params_from_dml(p,&mut (*ctx).bw_ctx.dml2.v20.dml_core_ctx,di as dml_uint_t); let mt=dc_state_get_pipe_subvp_type(ctx,p); if mt==SUBVP_PHANTOM{p.det_buffer_size_kb=0;p.unbounded_req=false;}else{p.det_buffer_size_kb=dml_get_det_buffer_size_kbytes(&mut (*ctx).bw_ctx.dml2.v20.dml_core_ctx,di as dml_uint_t);p.unbounded_req=(*in_ctx).v20.dml_core_ctx.ms.UnboundedRequestEnabledThisState;} (*ctx).bw_ctx.bw.dcn.compbuf_size_kb-=p.det_buffer_size_kb; p.plane_res.bw.dppclk_khz=(dml_get_dppclk_calculated(&mut (*ctx).bw_ctx.dml2.v20.dml_core_ctx,di as dml_uint_t)*1000.0) as i32; if (*ctx).bw_ctx.bw.dcn.clk.dppclk_khz<p.plane_res.bw.dppclk_khz{(*ctx).bw_ctx.bw.dcn.clk.dppclk_khz=p.plane_res.bw.dppclk_khz;} (*ctx).res_ctx.pipe_ctx[ci].surface_size_in_mall_bytes=dml_get_surface_size_for_mall(&mut (*ctx).bw_ctx.dml2.v20.dml_core_ctx,di as dml_uint_t); }
    (*ctx).bw_ctx.bw.dcn.clk.bw_dppclk_khz=(*ctx).bw_ctx.bw.dcn.clk.dppclk_khz; (*ctx).bw_ctx.bw.dcn.clk.bw_dispclk_khz=(*ctx).bw_ctx.bw.dcn.clk.dispclk_khz;
}

pub unsafe fn dml2_apply_det_buffer_allocation_policy(c:*mut dml2_context,cfg:*mut dml_display_cfg_st){ let max=c.as_ref().unwrap().config.det_segment_size*c.as_ref().unwrap().config.max_segments_per_hubp; for i in 0..(*cfg).num_surfaces as usize { (*cfg).plane.DETSizeOverride[i]=if (*c).config.override_det_buffer_size_kbytes{max/(*c).config.dcn_pipe_count}else{max/(*c).config.dcn_pipe_count}; } }
pub unsafe fn dml2_verify_det_buffer_configuration(c:*mut dml2_context,state:*mut dc_state,s:*mut dml2_helper_det_policy_scratch)->bool { let mut total=0; for i in 0..MAX_PIPES as usize {let p=&(*state).res_ctx.pipe_ctx[i];if p.stream.is_null(){continue;} let di=dml2_helper_find_dml_pipe_idx_by_stream_id(c,(*p.stream).stream_id);if di>=0{total+=dml_get_det_buffer_size_kbytes(&mut (*c).v20.dml_core_ctx,di as dml_uint_t);}} for i in 0..MAX_PLANES as usize{(*s).dpps_per_surface[i]=(*c).v20.scratch.cur_display_config.hw.DPPPerSurface[i];} total>(*c).config.det_segment_size*(*c).config.max_segments_per_hubp }

pub unsafe fn dml2_extract_writeback_wm(c:*mut dc_state,m:*mut display_mode_lib_st){ let mut n=0;for i in 0..(*c).stream_count as usize{if (*(*c).streams[i]).num_wb_info!=0{n+=1;}}if n==0{return;}for i in 0..__DML_NUM_DMB__ as usize{for j in 0..4{(*c).bw_ctx.bw.dcn.bw_writeback.mcif_wb_arb[i].cli_watermark[j]=(dml_get_wm_writeback_urgent(m)*1000.0) as u32;(*c).bw_ctx.bw.dcn.bw_writeback.mcif_wb_arb[i].pstate_watermark[j]=(dml_get_wm_writeback_dram_clock_change(m)*1000.0) as u32;}let a=&mut (*c).bw_ctx.bw.dcn.bw_writeback.mcif_wb_arb[i];if !(*c).res_ctx.pipe_ctx[i].stream.is_null()&&(*(*c).res_ctx.pipe_ctx[i].stream).phy_pix_clk!=0{a.time_per_pixel=(1000000<<6)/(*(*c).res_ctx.pipe_ctx[i].stream).phy_pix_clk;}a.slice_lines=32;a.arbitration_slice=2;a.max_scaled_time=dml2_calc_max_scaled_time(a.time_per_pixel,PACKED_444_FP16,a.cli_watermark[0]);a.dram_speed_change_duration=(dml_get_wm_writeback_dram_clock_change(m)*1000.0) as u32;}}

